head.script:
scwin.onpageload = function() {
    var selectData = [{
        "label": "l_a1",
        "value": "a1",
        "visibleData": "true"
    }, {
        "label": "l_a2",
        "value": "a2",
        "visibleData": "true"
    }, {
        "label": "l_b1",
        "value": "b1",
        "visibleData": "true"
    }, {
        "label": "l_b2",
        "value": "b2",
        "visibleData": "true"
    }, {
        "label": "l_b3",
        "value": "b3",
        "visibleData": "true"
    }, {
        "label": "l_c1",
        "value": "c1",
        "visibleData": "false"
    }, {
        "label": "l_c2",
        "value": "c2",
        "visibleData": "false"
    }];
    dl_chkcombo.setJSON(selectData);
    var jsonData = [{
        "col1": "c1",
        "col3": "c1"
    }, {
        "col1": "c2",
        "col3": "c2"
    }];
    dl_gridView.setJSON(jsonData);
    chkcombo1.setValue("c1");
};
scwin.onpageunload = function() {};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('chkcombo1_main_tbody').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('chkcombo1_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('chkcombo1_main_tbody').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'chkcombo1_label').innerText == 'l_a1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1___checkcombobox_col3_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_2').innerText == 'l_a1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
